function sourceBadge(s){let host='';try{host=new URL(s.url).hostname.replace(/^www\./,'');}catch{}const youtube=/^(youtube\.com|youtu\.be|m\.youtube\.com)$/.test(host),instagram=host==='instagram.com';let type=youtube?'youtube':instagram?'instagram':s.kind==='pdf'?'pdf':host?'web':s.kind==='docx'?'doc':s.kind==='transcript'?'audio':s.kind==='video-observations'?'video':'text';const label=({youtube:'YouTube',instagram:'Instagram',pdf:'PDF',web:host,doc:'Document',audio:'Audio transcript',video:'Video frames',text:'Text source'})[type];const badge=el('span',{class:'source-badge '+type,title:label,'aria-label':label},({youtube:'▶',instagram:'◎',pdf:'PDF',web:'↗',doc:'DOC',audio:'♫',video:'▷',text:'TXT'})[type]);if(type==='web'&&host.endsWith('wikipedia.org'))badge.textContent='W';return badge;}
function renderSpatialLibrary(list){spatialBooks=list;spatialIndex=Math.min(spatialIndex,Math.max(0,list.length-1));const active=libraryView==='spatial'&&list.length>0&&!shareToken;$('#spatial-library').hidden=!active;$('#notebooks').classList.toggle('list-fallback',active);document.querySelectorAll('[data-library-view]').forEach(b=>{b.classList.toggle('active',b.dataset.libraryView===libraryView);b.setAttribute('aria-pressed',String(b.dataset.libraryView===libraryView));});
 const stage=$('#spatial-stage');stage.replaceChildren(...list.map((n,i)=>{const offset=i-spatialIndex;const card=el('button',{class:'spatial-book',style:`--offset:${offset};--distance:${Math.abs(offset)};--cover:${i%5}`,'aria-label':n.title+(offset===0?', open notebook':', select notebook'),'aria-current':offset===0?'true':'false','data-far':Math.abs(offset)>2?'true':'false',tabindex:Math.abs(offset)>2?'-1':'0',onclick:()=>{if(performance.now()-lastShelfSwipe<400)return;if(i!==spatialIndex){spatialIndex=i;renderSpatialLibrary(spatialBooks);}else openNotebook(n.id).catch(e=>toast(e.message));}},el('span',{class:'book-spine','aria-hidden':'true'}),el('span',{class:'book-cover'},el('span',{class:'book-edition'},'SOURCEBOOK / '+String(i+1).padStart(2,'0')),el('strong',{},n.title),el('span',{class:'book-rule'}),el('small',{},`${n.source_count} sources`),el('span',{class:'book-open'},offset===0?'Open notebook ↗':'Select notebook')));card.inert=Math.abs(offset)>2;return card;}));$('#spatial-position').textContent=list.length?`${spatialIndex+1} / ${list.length}`:'No notebooks';$('#spatial-prev').disabled=spatialIndex===0;$('#spatial-next').disabled=spatialIndex>=list.length-1;
}
function shelfStep(delta){if(!spatialBooks.length)return;spatialIndex=Math.max(0,Math.min(spatialBooks.length-1,spatialIndex+delta));renderSpatialLibrary(spatialBooks);$('#spatial-stage').focus({preventScroll:true});}
document.querySelectorAll('[data-library-view]').forEach(b=>b.onclick=()=>{libraryView=b.dataset.libraryView;localStorage.setItem('sourcebook-library-view',libraryView);renderHome();});$('#spatial-prev').onclick=()=>shelfStep(-1);$('#spatial-next').onclick=()=>shelfStep(1);$('#spatial-stage').onkeydown=e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();shelfStep(e.key==='ArrowLeft'?-1:1);}else if((e.key==='Enter'||e.key===' ')&&e.target.id==='spatial-stage'&&spatialBooks[spatialIndex]){e.preventDefault();openNotebook(spatialBooks[spatialIndex].id).catch(err=>toast(err.message));}};let shelfTouch=null,lastShelfSwipe=-1000;$('#spatial-stage').addEventListener('touchstart',e=>{shelfTouch=e.touches[0].clientX;},{passive:true});$('#spatial-stage').addEventListener('touchend',e=>{if(shelfTouch===null)return;const delta=e.changedTouches[0].clientX-shelfTouch;if(Math.abs(delta)>45){lastShelfSwipe=performance.now();shelfStep(delta<0?1:-1);}shelfTouch=null;},{passive:true});
$('#discover-sources').onclick=async()=>{const nid=current.id,box=$('#source-discovery');box.hidden=false;box.replaceChildren(el('p',{class:'helper'},'Searching Wikipedia for this notebook title…'));try{const data=await api(path('/recommendations'));if(current?.id!==nid)return;box.replaceChildren(el('h3',{},'Suggested starting points'),el('p',{class:'helper'},data.notice),...data.suggestions.map(s=>{const add=el('button',{class:'secondary',onclick:async()=>{add.disabled=true;add.textContent='Importing…';try{const source=await api(path('/sources'),'POST',{title:s.title,kind:'url',url:s.url});if(current?.id===nid){selected.add(source.id);await openNotebook(nid,true);}add.textContent='Added';}catch(e){add.disabled=false;add.textContent='Add source';toast(e.message);}}},'Add source');return el('article',{class:'discovery-card'},el('div',{},el('strong',{},s.title),el('p',{class:'helper'},s.url),el('small',{},s.reason)),add);}));if(!data.suggestions.length)box.append(el('p',{class:'helper'},'No matching pages found. Rename the notebook more specifically or add a source URL.'));}catch(e){if(current?.id===nid)box.replaceChildren(el('p',{class:'error'},e.message));}};
